contract InvMutTest {
	C c;
	constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
	receive() external payable {}
	function test(address recipient) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
		require(msg.sender == c.owner());
		require(recipient != msg.sender);
		require(recipient.balance < type(uint256).max - address(c).balance);
		uint preRecipient = recipient.balance;
		require(address(this).balance > 0);
		c.withdrawAll(recipient); if (__ESBMC_reverted()) return;
		assert(recipient.balance > preRecipient);
	}
}

