// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Phishable c;

    function setUp() public {
        c = new Phishable(address(this));
    }

    function _test(address recipient) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(msg.sender == c.owner());
        vm.assume(recipient != msg.sender);
        vm.assume(recipient.balance < type(uint256).max - address(c).balance);
        uint preRecipient = recipient.balance;
        vm.assume(address(this).balance > 0);
        try c.withdrawAll(recipient) {} catch { return; }
        assertTrue(recipient.balance > preRecipient);
    }

    function testFuzz_test(address recipient) public {
        vm.assume(recipient.code.length == 0 && uint160(recipient) > 0xffff && recipient != address(this) && recipient != address(c) && recipient != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && recipient != 0x000000000000000000636F6e736F6c652e6c6f67 && recipient != 0x4e59b44847b379578588920cA78FbF26c0B4956C && recipient != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _test(recipient);
    }

    receive() external payable {}
}
